--region handler
function ActivityMidFestivalNode:OnClickBtnGroupHandler()
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._activityDojo.id)))
    if isNull(self._activityDojo) then
        return
    end
    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        GameUtils.Toast(err)
        return
    end
    KCookie.Set(Constants.EventNames.WayOfEnterMidFestivalActivity, Constants.WayOfOpenMidFestivalDialog.ActivityNode)
    ActivityMidFestivalMgr:EnterActivityDialog(self._activityDojo)
end
--endregion handler

--region public
---@param activityDojo ActivityDojo
function ActivityMidFestivalNode:Refresh(activityDojo)
    self._activityDojo = activityDojo

    if isNull(self._activityDojo) then
        return
    end
    local vo = self._activityDojo.unlock[1]
    self.isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)

    self:RefreshUI()
end
--endregion public

--region private
function ActivityMidFestivalNode:RefreshUI()
    self:RefreshActivityTime()
    self:RefreshStateGroup()
    self:RefreshEndTime()
    self:RefreshTitleImg()
end

function ActivityMidFestivalNode:RefreshTitleImg()
    local titleImgUrl = checkString(self._activityDojo.titleImage)
    if not string.isEmpty(titleImgUrl) then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
end

function ActivityMidFestivalNode:RefreshActivityTime()
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self._activityDojo.startTime, self._activityDojo.endTime))
end

function ActivityMidFestivalNode:RefreshStateGroup()
    CfUtils.FillText(self.Text, self._activityDojo.detail)
end

function ActivityMidFestivalNode:RefreshEndTime()
    ---@param tick number 具体日期的时间戳
    local tipsInfo = function(tick)
        -- 显示距离关闭的剩余天数 / 距离开启的剩余天数
        ---@type PlayerComponent
        local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
        local leftTime = tick - curDate
        if leftTime < 0 then
            return localize("已结束")
        end

        return CfUtils.GetTimeHMS7(leftTime)
    end

    CfUtils.FillText(self.TextTime2, tipsInfo(self._activityDojo.closeTime))

    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        CfUtils.FillText(self.TextLockDesc, err)
    end
    CfUtils.SetActive(self.ImgBg, self.isUnlock)
    CfUtils.SetActive(self.ImgLockBg, not self.isUnlock)
end
--endregion private

